import{_ as a,c as o,o as i,a3 as r}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Manual de Usuario: Reporte de Cubiertas","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/depositosCubiertas/index.md","filePath":"reportes/depositosCubiertas/index.md","lastUpdated":1759946186000}'),l={name:"reportes/depositosCubiertas/index.md"};function s(d,e,t,c,n,p){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="manual-de-usuario-reporte-de-cubiertas" tabindex="-1">Manual de Usuario: Reporte de Cubiertas <a class="header-anchor" href="#manual-de-usuario-reporte-de-cubiertas" aria-label="Permalink to &quot;Manual de Usuario: Reporte de Cubiertas&quot;">​</a></h1><h2 id="_1-descripcion-general" tabindex="-1">1. Descripción general <a class="header-anchor" href="#_1-descripcion-general" aria-label="Permalink to &quot;1. Descripción general&quot;">​</a></h2><p>Este reporte permite visualizar el estado y el lugar donde se encuentran las cubiertas (neumáticos) en los distintos depósitos (tractores, semis o lugares) de la empresa. Dependiendo del tipo de depósito seleccionado, el reporte muestra la información en dos formatos:</p><ol><li><strong>Depósitos de camiones (tractores o semis):</strong> se visualiza como un esquema gráfico con posiciones de cubiertas y movimientos de entrada/salida.</li><li><strong>Depósitos de recapeado o cubiertas para recapar:</strong> se visualiza como una tabla con detalle de cada cubierta, su marca, modelo, tipo de movimiento y fecha.</li></ol><h2 id="_2-seleccion-de-deposito" tabindex="-1">2. Selección de depósito <a class="header-anchor" href="#_2-seleccion-de-deposito" aria-label="Permalink to &quot;2. Selección de depósito&quot;">​</a></h2><ol><li><p>En la sección izquierda, encontrarás un <strong>desplegable llamado <code>Deposito</code></strong>.</p></li><li><p>Puedes buscar o seleccionar el depósito deseado.</p><ul><li>Ejemplo: <code>AE236PI</code> (depósito de camiones)</li><li>Ejemplo: <code>CUBIERTAS</code> (depósito de recapeado)</li></ul></li><li><p>Presiona el botón <strong>Aplicar</strong> para que el reporte se actualice según tu selección.</p></li></ol><h2 id="_3-visualizacion-del-reporte" tabindex="-1">3. Visualización del reporte <a class="header-anchor" href="#_3-visualizacion-del-reporte" aria-label="Permalink to &quot;3. Visualización del reporte&quot;">​</a></h2><h3 id="_3-1-depositos-de-camiones" tabindex="-1">3.1. Depósitos de camiones <a class="header-anchor" href="#_3-1-depositos-de-camiones" aria-label="Permalink to &quot;3.1. Depósitos de camiones&quot;">​</a></h3><ul><li><p>Se muestra un <strong>diagrama con las posiciones de las cubiertas</strong> en cada camión o semi.</p></li><li><p><strong>Columnas y filas:</strong></p><ul><li><code>C</code>: Coloca(Código que se coloca)</li><li><code>R</code>: Retira (Código que se retira)</li></ul></li><li><p><strong>Secciones:</strong></p><ul><li><strong>ENTRA:</strong> cubiertas que han ingresado recientemente al depósito.</li><li><strong>SALE:</strong> cubiertas que han sido retiradas o dadas de baja.</li></ul></li><li><p><strong>Detalle por entrada/salida:</strong></p><ul><li>Fecha de carga</li><li>Marca</li><li>Código</li><li>Modelo / Fecha / Tipo / Medida</li><li>Estado</li><li>Posición en el camión</li></ul></li></ul><p><strong>Ejemplo de interpretación:</strong></p><ul><li><p>Cubierta en posición 17 del camión AE236PI:</p><ul><li>Entró: <code>FATE 988912</code> (recapada)</li><li>Salió: <code>FATE CARGO 711280</code> (para dar de baja)</li></ul></li></ul><h3 id="_3-2-depositos-de-recapeado-imagen-2" tabindex="-1">3.2. Depósitos de recapeado (Imagen 2) <a class="header-anchor" href="#_3-2-depositos-de-recapeado-imagen-2" aria-label="Permalink to &quot;3.2. Depósitos de recapeado (Imagen 2)&quot;">​</a></h3><ul><li><p>Se muestra una <strong>tabla con todas las cubiertas disponibles o recapeadas</strong> en el depósito.</p></li><li><p><strong>Columnas principales:</strong></p><ul><li><code>Internalcode</code>: código interno de la cubierta.</li><li><code>Marca</code>: marca del neumático.</li><li><code>Modelo - fecha - tipo - medida</code>: detalle técnico de la cubierta.</li><li><code>Movimiento</code>: tipo de movimiento (<code>ARTICULOS</code> , <code>MANTENIMIENTO</code> , <code>COMPRAS</code>).</li><li><code>Fecha</code>: fecha del movimiento registrado.</li></ul></li></ul><p><strong>Ejemplo de interpretación:</strong></p><ul><li><p>Cubierta <code>VCI20507A</code> de marca <code>MICHELIN</code>:</p><ul><li>Tipo de movimiento: <code>MANTENIMIENTO</code></li><li>Fecha: <code>1/09/25</code></li></ul></li><li><p>Cubierta <code>711175</code> de marca <code>FATE CARGO</code>:</p><ul><li>Tipo de movimiento: <code>ARTICULOS</code> (entrada/salida para recapar)</li></ul></li></ul><h2 id="_4-recomendaciones-de-uso" tabindex="-1">4. Recomendaciones de uso <a class="header-anchor" href="#_4-recomendaciones-de-uso" aria-label="Permalink to &quot;4. Recomendaciones de uso&quot;">​</a></h2><ol><li>Antes de aplicar filtros, asegúrate de <strong>seleccionar el depósito correcto</strong> según la información que necesites.</li><li>Si el depósito es de camiones, revisa la <strong>posición específica de cada cubierta</strong> para ver su estado.</li><li>Si el depósito es de recapeado, la <strong>tabla permite buscar cubiertas por marca, modelo o código</strong> para seguimiento detallado.</li><li>Utiliza la información de <strong>ENTRA / SALE</strong> para controlar el inventario y las rotaciones de cubiertas.</li><li>Para reportes impresos o exportación, verifica que el depósito seleccionado esté cargado correctamente antes de generar el PDF o Excel.</li></ol>',17)]))}const g=a(l,[["render",s]]);export{m as __pageData,g as default};
